mapper.update:
update course_selection
student_id = #{studentId}, course_id = #{courseId},
where id = #{id}

mapper.select:
select cs.*, s.student_name, c.course_name from course_selection cs left join student s on cs.student_id = s.student_id left join course c on cs.course_id = c.course_id
and cs.student_id = #{studentId}
and cs.course_id = #{courseId}
order by cs.id desc
